// Automation Inbox — handles both GitHub issue events and custom payloads
const body = $input.first().json.body || $input.first().json;

let type, title, issueBody, priority;

if (body.action && body.issue) {
  // GitHub Issue Event payload
  const issue = body.issue;
  const labels = (issue.labels || []).map(l => l.name);

  // Determine type from labels (bug > feature > note)
  if (labels.includes('bug')) type = 'bug';
  else if (labels.includes('feature')) type = 'feature';
  else type = 'note';

  title = issue.title;
  issueBody = issue.body || '';
  priority = labels.includes('critical') ? 'critical' : labels.includes('high') ? 'high' : 'medium';

  // Skip non-opened events
  if (body.action !== 'opened') {
    return [{json: {status: 'skipped', reason: 'action=' + body.action}}];
  }
} else {
  // Custom payload format (direct webhook call)
  type = body.type || 'note';
  title = body.title || 'Untitled';
  issueBody = body.body || body.description || '';
  priority = body.priority || 'medium';
}

const fullTitle = type + ': ' + title;
const fullBody = '**Type:** ' + type + '\n**Priority:** ' + priority + '\n\n' + issueBody;

const ghToken = '${GITHUB_TOKEN}';
const data = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.github.com/repos/${GITHUB_REPO}/issues',
  headers: {
    'Authorization': 'token ' + ghToken,
    'User-Agent': 'n8n-automation',
    'Accept': 'application/vnd.github.v3+json'
  },
  body: { title: fullTitle, body: fullBody, labels: [type] },
  json: true
});

return [{json: {status: 'ok', issue: data.number, url: data.html_url}}];
